import Foundation
import Security

protocol LLMCredentialStoring {
    func readAPIKey() throws -> String?
    func writeAPIKey(_ apiKey: String) throws
}

struct KeychainLLMCredentialStore: LLMCredentialStoring {
    static let credentialAccessibility = kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly

    private let service: String
    private let account: String

    init(
        service: String = "me.mezorewww.timetracker.credentials",
        account: String = "llm-api-key"
    ) {
        self.service = service
        self.account = account
    }

    func readAPIKey() throws -> String? {
        var query = baseQuery
        query[kSecReturnData as String] = true
        query[kSecMatchLimit as String] = kSecMatchLimitOne

        var result: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &result)
        if status == errSecItemNotFound {
            return nil
        }
        guard status == errSecSuccess else {
            throw KeychainCredentialError(status: status)
        }
        guard let data = result as? Data,
              let value = String(data: data, encoding: .utf8)
        else {
            throw KeychainCredentialError.invalidData
        }
        let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return normalized.isEmpty ? nil : normalized
    }

    func writeAPIKey(_ apiKey: String) throws {
        let normalized = apiKey.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalized.isEmpty else {
            let status = SecItemDelete(baseQuery as CFDictionary)
            guard status == errSecSuccess || status == errSecItemNotFound else {
                throw KeychainCredentialError(status: status)
            }
            return
        }

        let data = Data(normalized.utf8)
        let updateStatus = SecItemUpdate(
            baseQuery as CFDictionary,
            [
                kSecValueData as String: data,
                kSecAttrAccessible as String: Self.credentialAccessibility,
            ] as CFDictionary
        )
        if updateStatus == errSecSuccess {
            return
        }
        guard updateStatus == errSecItemNotFound else {
            throw KeychainCredentialError(status: updateStatus)
        }

        var item = baseQuery
        item[kSecValueData as String] = data
        item[kSecAttrAccessible as String] = Self.credentialAccessibility
        let addStatus = SecItemAdd(item as CFDictionary, nil)
        guard addStatus == errSecSuccess else {
            throw KeychainCredentialError(status: addStatus)
        }
    }

    private var baseQuery: [String: Any] {
        [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecAttrSynchronizable as String: kCFBooleanFalse as Any,
        ]
    }
}

enum KeychainCredentialError: LocalizedError {
    case invalidData
    case operationFailed(OSStatus)

    init(status: OSStatus) {
        self = .operationFailed(status)
    }

    var errorDescription: String? {
        switch self {
        case .invalidData:
            return String(localized: "error.keychain.invalidData")
        case let .operationFailed(status):
            let message = SecCopyErrorMessageString(status, nil) as String? ??
                String(localized: "error.keychain.unknownFailure")
            return String(
                format: String(localized: "error.keychain.operationFailedFormat"),
                Int64(status),
                message
            )
        }
    }
}

import Foundation
import Testing
@testable import timetracker

@Suite(.serialized)
struct CoreLLMResponseTransportTests {
    @Test
    func productionSessionIsEphemeralAndResourceBounded() {
        let configuration = LLMSecureHTTPTransport.productionConfiguration()

        #expect(LLMSecureHTTPTransport.maximumResponseByteCount == 2 * 1024 * 1024)
        #expect(configuration.timeoutIntervalForResource == 60)
        #expect(configuration.requestCachePolicy == .reloadIgnoringLocalCacheData)
        #expect(configuration.urlCache == nil)
        #expect(configuration.httpShouldSetCookies == false)
        #expect(configuration.httpCookieStorage == nil)
    }

    @Test
    func streamingTransportAcceptsTheExactByteLimit() async throws {
        let exchange = LLMTransportTestExchange(
            behavior: .complete(statusCode: 200, headers: [:], body: Data(repeating: 0x41, count: 64))
        )
        let fixture = Self.fixture(exchange: exchange)
        defer { fixture.session.invalidateAndCancel() }

        let (data, response) = try await LLMSecureHTTPTransport.data(
            for: URLRequest(url: fixture.url),
            session: fixture.session,
            maximumResponseByteCount: 64
        )

        #expect(data == Data(repeating: 0x41, count: 64))
        #expect((response as? HTTPURLResponse)?.statusCode == 200)
    }

    @Test
    func streamingTransportCancelsAtTheFirstByteBeyondTheLimit() async {
        let exchange = LLMTransportTestExchange(
            behavior: .complete(statusCode: 200, headers: [:], body: Data(repeating: 0x42, count: 65))
        )
        let fixture = Self.fixture(exchange: exchange)
        defer { fixture.session.invalidateAndCancel() }

        await Self.expectResponseTooLarge {
            _ = try await LLMSecureHTTPTransport.data(
                for: URLRequest(url: fixture.url),
                session: fixture.session,
                maximumResponseByteCount: 64
            )
        }
        #expect(await Self.eventually { exchange.wasStopped })
    }

    @Test
    func cancellationPropagatesWhileWaitingForResponseHeaders() async {
        let exchange = LLMTransportTestExchange(behavior: .pending)
        let fixture = Self.fixture(exchange: exchange)
        defer { fixture.session.invalidateAndCancel() }
        let transportTask = Task {
            try await LLMSecureHTTPTransport.data(
                for: URLRequest(url: fixture.url),
                session: fixture.session,
                maximumResponseByteCount: 64
            )
        }

        #expect(await Self.eventually { exchange.didStart })
        transportTask.cancel()
        await Self.expectCancellation(from: transportTask)
        #expect(await Self.eventually { exchange.wasStopped })
    }

    @Test
    func URLTimeoutBecomesTypedTransportTimeout() async throws {
        let exchange = LLMTransportTestExchange(behavior: .fail(.timedOut))
        let fixture = Self.fixture(exchange: exchange)
        defer { fixture.session.invalidateAndCancel() }

        do {
            _ = try await LLMSecureHTTPTransport.data(
                for: URLRequest(url: fixture.url),
                session: fixture.session,
                maximumResponseByteCount: 64
            )
            Issue.record("Expected typed timeout")
        } catch let error as LLMModelServiceError {
            #expect(error == .timeout)
        }
    }

    @Test
    func modelServiceDefendsAgainstOversizedInjectedTransportData() async {
        let service = LLMModelService(transport: Self.oversizedInjectedTransport)

        await Self.expectResponseTooLarge {
            _ = try await service.fetchModels(endpoint: "https://example.test/v1", apiKey: "key")
        }
    }

    @Test
    func injectedTransportPreservesHTTPStatusPriorityOverBufferedBodyLimit() async throws {
        let service = LLMModelService { request in
            let response = try #require(
                HTTPURLResponse(
                    url: request.url ?? URL(string: "https://example.test")!,
                    statusCode: 429,
                    httpVersion: nil,
                    headerFields: nil
                )
            )
            return (Data(count: LLMSecureHTTPTransport.maximumResponseByteCount + 1), response)
        }

        do {
            _ = try await service.fetchModels(endpoint: "https://example.test/v1", apiKey: "key")
            Issue.record("Expected HTTP status failure")
        } catch let error as LLMModelServiceError {
            #expect(error == .responseStatus(429))
        }
    }

    @Test
    func inboxServiceDefendsAgainstOversizedInjectedTransportData() async {
        let service = LLMInboxSuggestionService(transport: Self.oversizedInjectedTransport)
        let candidate = LLMTaskCandidate(
            id: UUID(),
            title: "Design",
            path: "Work / Design",
            iconName: "paintbrush",
            colorHex: "1677FF"
        )

        await Self.expectResponseTooLarge {
            _ = try await service.suggest(
                inboxTitle: "Polish spacing",
                taskCandidates: [candidate],
                categoryCandidates: [],
                configuration: LLMRequestConfiguration(
                    endpoint: "https://example.test/v1",
                    apiKey: "key",
                    modelID: "model",
                    reasoningEffort: .high
                )
            )
        }
    }

    @Test
    func checklistServiceDefendsAgainstOversizedInjectedTransportData() async {
        let service = LLMChecklistVisualSuggestionService(transport: Self.oversizedInjectedTransport)

        await Self.expectResponseTooLarge {
            _ = try await service.suggest(
                checklistTitle: "Polish spacing",
                taskTitle: "Design",
                taskPath: "Work / Design",
                configuration: LLMRequestConfiguration(
                    endpoint: "https://example.test/v1",
                    apiKey: "key",
                    modelID: "model",
                    reasoningEffort: .high
                )
            )
        }
    }

    @Test
    func responseLimitErrorsHaveLocalizedDescriptions() throws {
        let responseTooLarge = try #require(LLMModelServiceError.responseTooLarge.errorDescription)
        let timeout = try #require(LLMModelServiceError.timeout.errorDescription)

        #expect([
            "The server response was too large.",
            "服务器返回的内容过大。",
            "伺服器返回的內容過大。",
        ].contains(responseTooLarge))
        #expect([
            "The server took too long to respond.",
            "服务器响应超时。",
            "伺服器回應逾時。",
        ].contains(timeout))
    }

    private static let oversizedInjectedTransport: LLMModelService.Transport = { request in
        let response = try #require(
            HTTPURLResponse(
                url: request.url ?? URL(string: "https://example.test")!,
                statusCode: 200,
                httpVersion: nil,
                headerFields: nil
            )
        )
        return (Data(count: LLMSecureHTTPTransport.maximumResponseByteCount + 1), response)
    }

    private static func fixture(exchange: LLMTransportTestExchange) -> (url: URL, session: URLSession) {
        let url = URL(string: "https://llm-transport.test/\(UUID().uuidString)")!
        LLMTransportTestURLProtocol.registry.register(exchange, for: url)
        let configuration = URLSessionConfiguration.ephemeral
        configuration.protocolClasses = [LLMTransportTestURLProtocol.self]
        configuration.urlCache = nil
        return (url, URLSession(configuration: configuration))
    }

    private static func expectResponseTooLarge(_ operation: () async throws -> Void) async {
        do {
            try await operation()
            Issue.record("Expected oversized response to be rejected")
        } catch let error as LLMModelServiceError {
            #expect(error == .responseTooLarge)
        } catch {
            Issue.record("Unexpected error: \(error)")
        }
    }

    private static func expectCancellation(
        from task: Task<(Data, URLResponse), Error>
    ) async {
        do {
            _ = try await task.value
            Issue.record("Expected cancellation")
        } catch is CancellationError {
            return
        } catch {
            Issue.record("Unexpected cancellation error: \(error)")
        }
    }

    private static func eventually(
        timeout: Duration = .seconds(2),
        condition: @escaping @Sendable () -> Bool
    ) async -> Bool {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: timeout)
        while clock.now < deadline {
            if condition() {
                return true
            }
            try? await Task.sleep(for: .milliseconds(10))
        }
        return condition()
    }
}

private final nonisolated class LLMTransportTestExchange: @unchecked Sendable {
    enum Behavior: Sendable {
        case complete(statusCode: Int, headers: [String: String], body: Data)
        case pending
        case fail(URLError.Code)
    }

    let behavior: Behavior
    private let lock = NSLock()
    private var started = false
    private var responseDelivered = false
    private var stopped = false

    init(behavior: Behavior) {
        self.behavior = behavior
    }

    var didStart: Bool {
        lock.withLock { started }
    }

    var didDeliverResponse: Bool {
        lock.withLock { responseDelivered }
    }

    var wasStopped: Bool {
        lock.withLock { stopped }
    }

    func markStarted() {
        lock.withLock { started = true }
    }

    func markResponseDelivered() {
        lock.withLock { responseDelivered = true }
    }

    func markStopped() {
        lock.withLock { stopped = true }
    }
}

private final nonisolated class LLMTransportTestRegistry: @unchecked Sendable {
    private let lock = NSLock()
    private var exchanges: [URL: LLMTransportTestExchange] = [:]

    func register(_ exchange: LLMTransportTestExchange, for url: URL) {
        lock.withLock { exchanges[url] = exchange }
    }

    func exchange(for url: URL) -> LLMTransportTestExchange? {
        lock.withLock { exchanges[url] }
    }
}

private final nonisolated class LLMTransportTestURLProtocol: URLProtocol, @unchecked Sendable {
    static let registry = LLMTransportTestRegistry()
    private var exchange: LLMTransportTestExchange?

    override class func canInit(with _: URLRequest) -> Bool {
        true
    }

    override class func canonicalRequest(for request: URLRequest) -> URLRequest {
        request
    }

    override func startLoading() {
        guard let url = request.url,
              let exchange = Self.registry.exchange(for: url)
        else {
            client?.urlProtocol(self, didFailWithError: URLError(.badURL))
            return
        }
        self.exchange = exchange
        exchange.markStarted()

        switch exchange.behavior {
        case let .complete(statusCode, headers, body):
            deliverResponse(statusCode: statusCode, headers: headers, exchange: exchange)
            client?.urlProtocol(self, didLoad: body)
            client?.urlProtocolDidFinishLoading(self)
        case .pending:
            break
        case let .fail(code):
            client?.urlProtocol(self, didFailWithError: URLError(code))
        }
    }

    override func stopLoading() {
        exchange?.markStopped()
    }

    private func deliverResponse(
        statusCode: Int,
        headers: [String: String],
        exchange: LLMTransportTestExchange
    ) {
        guard let url = request.url,
              let response = HTTPURLResponse(
                  url: url,
                  statusCode: statusCode,
                  httpVersion: "HTTP/1.1",
                  headerFields: headers
              )
        else {
            client?.urlProtocol(self, didFailWithError: URLError(.badServerResponse))
            return
        }
        exchange.markResponseDelivered()
        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
    }
}

import Foundation
import SwiftData
import Testing
@testable import timetracker

@Suite(.serialized)
struct DataModelContractTests {
    @Test @MainActor
    func persistentDeduplicationUsesLastWriteWinsForTombstonesAndRestores() {
        let id = UUID()
        let base = Date(timeIntervalSinceReferenceDate: 100_000)
        let oldActive = TaskNode(title: "Old active", parentID: nil, deviceID: "test")
        oldActive.id = id
        oldActive.createdAt = base
        oldActive.updatedAt = base

        let newTombstone = TaskNode(title: "Deleted", parentID: nil, deviceID: "test")
        newTombstone.id = id
        newTombstone.createdAt = base
        newTombstone.updatedAt = base.addingTimeInterval(10)
        newTombstone.deletedAt = newTombstone.updatedAt

        let deletedWinner = [oldActive, newTombstone].deduplicatedByID()
        #expect(deletedWinner.count == 1)
        #expect(deletedWinner.first === newTombstone)

        let restored = TaskNode(title: "Restored", parentID: nil, deviceID: "test")
        restored.id = id
        restored.createdAt = base
        restored.updatedAt = base.addingTimeInterval(20)

        let restoredWinner = [newTombstone, restored].deduplicatedByID()
        #expect(restoredWinner.count == 1)
        #expect(restoredWinner.first === restored)
    }

    @Test @MainActor
    func persistentDeduplicationTieBreakIsStableAcrossFetchOrder() {
        let id = UUID()
        let timestamp = Date(timeIntervalSinceReferenceDate: 100_000)
        let first = TaskNode(title: "First", parentID: nil, deviceID: "device-a")
        first.id = id
        first.createdAt = timestamp
        first.updatedAt = timestamp
        let second = TaskNode(title: "Second", parentID: nil, deviceID: "device-b")
        second.id = id
        second.createdAt = timestamp
        second.updatedAt = timestamp

        #expect([first, second].deduplicatedByID().first === second)
        #expect([second, first].deduplicatedByID().first === second)
    }

    @Test @MainActor
    func duplicateCleanupKeepsTheCanonicalActiveRowNewerThanItsTombstone() {
        let id = UUID()
        let base = Date(timeIntervalSinceReferenceDate: 100_000)
        let older = TaskNode(title: "Older", parentID: nil, deviceID: "old")
        older.id = id
        older.createdAt = base
        older.updatedAt = base
        let newer = TaskNode(title: "Newer", parentID: nil, deviceID: "new")
        newer.id = id
        newer.createdAt = base.addingTimeInterval(10)
        newer.updatedAt = base.addingTimeInterval(10)
        let cleanupDate = base.addingTimeInterval(20)

        let latest = [older, newer].latestByIDMarkingDuplicatesDeleted(
            now: cleanupDate,
            deviceID: "cleanup"
        )

        #expect(latest[id] === newer)
        #expect(older.deletedAt != nil)
        #expect(newer.deletedAt == nil)
        #expect(newer.updatedAt == cleanupDate)
        #expect([older, newer].deduplicatedByID().first === newer)
    }

    @Test @MainActor
    func duplicateCleanupDoesNotRefreshAnOlderTombstonePastANewerRestore() {
        let id = UUID()
        let base = Date(timeIntervalSinceReferenceDate: 100_000)
        let tombstone = TaskNode(title: "Deleted", parentID: nil, deviceID: "old")
        tombstone.id = id
        tombstone.createdAt = base
        tombstone.updatedAt = base.addingTimeInterval(10)
        tombstone.deletedAt = tombstone.updatedAt
        let originalTombstoneUpdate = tombstone.updatedAt
        let restored = TaskNode(title: "Restored", parentID: nil, deviceID: "new")
        restored.id = id
        restored.createdAt = base
        restored.updatedAt = base.addingTimeInterval(20)

        let latest = [tombstone, restored].latestByIDMarkingDuplicatesDeleted(
            now: base.addingTimeInterval(30),
            deviceID: "cleanup"
        )

        #expect(latest[id] === restored)
        #expect(tombstone.updatedAt == originalTombstoneUpdate)
        #expect([tombstone, restored].deduplicatedByID().first === restored)
    }

    @Test @MainActor
    func modelDefaultsSupportCloudKitCompatibleConstruction() throws {
        let context = try makeTestContext()
        let task = TaskNode(title: "Defaults", parentID: nil, deviceID: "test")
        let session = TimeSession(taskID: task.id, source: .timer, deviceID: "test")
        let segment = TimeSegment(sessionID: session.id, taskID: task.id, source: .timer, deviceID: "test")
        let run = PomodoroRun(taskID: task.id, deviceID: "test")
        let countdown = CountdownEvent(title: "Launch", date: Date(), deviceID: "test")
        let recurrenceRule = TaskRecurrenceRule(
            templateTaskID: task.id,
            startDayKey: "2026-07-20",
            timeZoneIdentifier: "Asia/Singapore",
            deviceID: "test"
        )
        let recurrenceOccurrence = TaskRecurrenceOccurrence(
            ruleID: recurrenceRule.id,
            templateTaskID: task.id,
            occurrenceDayKey: "2026-07-20",
            timeZoneIdentifier: recurrenceRule.timeZoneIdentifier,
            deviceID: "test"
        )
        let quantityGoal = TaskQuantityGoal(
            taskID: task.id,
            targetAmount: 50,
            unitLabel: "push-ups",
            deviceID: "test"
        )
        let quantityEntry = TaskQuantityEntry(
            id: UUID(),
            taskID: task.id,
            amount: 10,
            deviceID: "test"
        )

        context.insert(task)
        context.insert(session)
        context.insert(segment)
        context.insert(run)
        context.insert(countdown)
        context.insert(recurrenceRule)
        context.insert(recurrenceOccurrence)
        context.insert(quantityGoal)
        context.insert(quantityEntry)
        try context.save()

        #expect(recurrenceRule.id == TaskProgressIdentity.recurrenceRuleID(templateTaskID: task.id))
        #expect(recurrenceOccurrence.generatedTaskID == TaskProgressIdentity.generatedTaskID(
            ruleID: recurrenceRule.id,
            dayKey: recurrenceOccurrence.occurrenceDayKey
        ))
        #expect(quantityGoal.id == TaskProgressIdentity.quantityGoalID(taskID: task.id))
        #expect(quantityEntry.quantityGoalID == quantityGoal.id)
    }

    @Test @MainActor
    func cloudSyncedSchemaIncludesChecklistAndAllUserDataModels() throws {
        let requiredModelNames: Set = [
            "TaskNode",
            "TaskCategory",
            "TaskCategoryAssignment",
            "TimeSession",
            "TimeSegment",
            "PomodoroRun",
            "CountdownEvent",
            "SyncedPreference",
            "ChecklistItem",
            "ChecklistItemVisual",
            "InboxItem",
            "InboxSuggestion",
            "InboxCaptureReceipt",
            "TaskRecurrenceRule",
            "TaskRecurrenceOccurrence",
            "TaskQuantityGoal",
            "TaskQuantityEntry",
        ]

        #expect(requiredModelNames.isSubset(of: TimeTrackerModelRegistry.cloudSyncedUserModelNames))
        #expect(requiredModelNames.isSubset(of: Set(TimeTrackerModelRegistry.currentSchema.entities.map(\.name))))
        #expect(TimeTrackerModelRegistry.cloudSyncedUserModelNames.contains("DailySummary") == false)
        #expect(TimeTrackerModelRegistry.currentSchema.entity(for: DailySummary.self) == nil)

        let schema = TimeTrackerModelRegistry.currentSchema
        #expect(schema.entity(for: TaskRecurrenceRule.self) != nil)
        #expect(schema.entity(for: TaskRecurrenceOccurrence.self) != nil)
        #expect(schema.entity(for: TaskQuantityGoal.self) != nil)
        #expect(schema.entity(for: TaskQuantityEntry.self) != nil)
        #expect(
            TimeTrackerMigrationPlan.schemas.last?.versionIdentifier
                == TimeTrackerSchemaV14.versionIdentifier
        )
        // Every cloud-synced entity must resolve together when the schema is
        // instantiated into a container; the name-set assertions above prove the
        // membership, so no per-model insert/fetch round trip is needed.
        let configuration = ModelConfiguration(
            "TimeTrackerCloudSyncContract",
            schema: schema,
            isStoredInMemoryOnly: true,
            cloudKitDatabase: .none
        )
        _ = try ModelContainer(
            for: schema,
            migrationPlan: TimeTrackerMigrationPlan.self,
            configurations: [configuration]
        )
    }

    @Test @MainActor
    func versionEightStoreMigratesToCurrentSchemaWithoutTheLegacyDailySummaryCache() throws {
        let fixture = try LegacyV8DailySummaryStoreFixture.create()

        try fixture.withCurrentContext { context in
            let taskIDs = try context.fetch(FetchDescriptor<TaskNode>()).map(\.id)
            #expect(taskIDs == [fixture.taskID])
            #expect(TimeTrackerModelRegistry.currentSchema.entity(for: DailySummary.self) == nil)
            #expect(TimeTrackerMigrationPlan.schemas.last?.versionIdentifier == TimeTrackerSchemaV14.versionIdentifier)
        }
    }

    @Test @MainActor
    func versionNineStoreMigratesInboxSuggestionIdentityAndDismissalState() throws {
        let fixture = try LegacyV9InboxStoreFixture.create()

        try fixture.withCurrentContext { context in
            let items = try context.fetch(FetchDescriptor<InboxItem>())
            let suggestions = try context.fetch(FetchDescriptor<InboxSuggestion>())
            let dismissedItem = try #require(items.first { $0.id == fixture.dismissedItemID })
            let readyItem = try #require(items.first { $0.id == fixture.readyItemID })
            let suggestion = try #require(suggestions.first { $0.id == fixture.suggestionID })

            #expect(dismissedItem.suggestionContextID == fixture.dismissedItemID)
            #expect(dismissedItem.suggestionRevisionID == fixture.dismissedItemID)
            #expect(dismissedItem.dismissedSuggestionRevisionID == fixture.dismissedItemID)
            #expect(
                InboxSuggestionStateService().state(
                    for: dismissedItem,
                    suggestion: nil,
                    isInFlight: false
                ) == .dismissed
            )
            #expect(readyItem.suggestionContextID == fixture.readyItemID)
            #expect(readyItem.suggestionRevisionID == fixture.readyItemID)
            #expect(readyItem.dismissedSuggestionRevisionID == nil)
            #expect(suggestion.inboxItemContextID == fixture.readyItemID)
            #expect(suggestion.inboxItemRevisionID == fixture.readyItemID)
            #expect(suggestion.belongs(to: readyItem))
        }
    }

    @Test @MainActor
    func applyingInboxSuggestionCreatesChecklistWithVisualAndRemovesInboxItem() throws {
        let context = try makeTestContext()
        let taskRepository = SwiftDataTaskRepository(context: context, deviceID: "test")
        let task = try taskRepository.createTask(title: "Design", parentID: nil, colorHex: "1677FF", iconName: "paintbrush")
        let inboxItem = InboxItem(title: "Polish empty state", deviceID: "test")
        let suggestion = InboxSuggestion(
            inboxItemID: inboxItem.id,
            taskID: task.id,
            reason: "Same design project",
            iconName: "paintbrush",
            colorHex: "1677FF",
            modelID: "gpt-test",
            titleSnapshot: inboxItem.title,
            deviceID: "test"
        )
        context.insert(inboxItem)
        context.insert(suggestion)
        try context.save()

        _ = try InboxCommandHandler().applySuggestion(
            item: inboxItem,
            suggestion: suggestion,
            existingChecklistItems: [],
            context: context,
            deviceID: "test"
        )

        let checklistItems = try context.fetch(FetchDescriptor<ChecklistItem>())
        let visuals = try context.fetch(FetchDescriptor<ChecklistItemVisual>())
        #expect(checklistItems.map(\.title) == ["Polish empty state"])
        #expect(checklistItems.first?.taskID == task.id)
        #expect(visuals.map(\.iconName) == ["paintbrush"])
        #expect(visuals.map(\.colorHex) == ["1677FF"])
        #expect(visuals.map(\.suggestionTitleSnapshot) == ["Polish empty state"])
        #expect(visuals.map(\.suggestionModelID) == ["gpt-test"])
        #expect(inboxItem.deletedAt != nil)
        #expect(suggestion.deletedAt != nil)
    }

    @Test @MainActor
    func legacyTaskStatusRawValuesRemainPersistableButOnlyArchiveChangesLifecycle() throws {
        let context = try makeTestContext()
        let repository = SwiftDataTaskRepository(context: context, deviceID: "test")
        let task = try repository.createTask(title: "Plan draft", parentID: nil, colorHex: nil, iconName: nil)

