    private func makeCategory(
        id: UUID = UUID(),
        title: String = "Category"
    ) -> AITaskWorkspaceCategory {
        AITaskWorkspaceCategory(
            id: id,
            title: title,
            iconName: "folder",
            colorHex: "007AFF",
            includesInForecast: true,
            sortOrder: 0
        )
    }

    private func makeTask(
        id: UUID = UUID(),
        categoryID: UUID? = nil,
        quantityGoal: TaskQuantityGoalDraft? = nil
    ) -> AITaskWorkspaceTask {
        AITaskWorkspaceTask(
            id: id,
            title: "Before",
            parentID: nil,
            categoryID: categoryID,
            path: "Before",
            notes: "",
            estimatedMinutes: nil,
            dueAt: nil,
            iconName: "circle",
            colorHex: "007AFF",
            sortOrder: 0,
            isArchived: false,
            quantityGoal: quantityGoal,
            dailyRecurrence: nil
        )
    }

    private func makeChecklist(
        id: UUID = UUID(),
        taskID: UUID
    ) -> AITaskWorkspaceChecklistItem {
        AITaskWorkspaceChecklistItem(
            id: id,
            taskID: taskID,
            title: "Before",
            isCompleted: false,
            iconName: "circle",
            colorHex: "007AFF",
            sortOrder: 0
        )
    }

    private func changed(
        _ task: AITaskWorkspaceTask,
        title: String? = nil,
        isArchived: Bool? = nil,
        quantityGoal: TaskQuantityGoalDraft?? = nil
    ) -> AITaskWorkspaceTask {
        var result = task
        if let title {
            result.title = title; result.path = title
        }
        if let isArchived {
            result.isArchived = isArchived
        }
        if let quantityGoal {
            result.quantityGoal = quantityGoal
        }
        return result
    }

    private func changed(
        _ item: AITaskWorkspaceChecklistItem,
        title: String
    ) -> AITaskWorkspaceChecklistItem {
        var result = item
        result.title = title
        return result
    }

    private func snapshot(
        category: AITaskWorkspaceCategory? = nil,
        task: AITaskWorkspaceTask? = nil,
        checklist: AITaskWorkspaceChecklistItem? = nil
    ) -> AITaskWorkspaceSnapshot {
        AITaskWorkspaceSnapshot(
            categories: category.map { [$0] } ?? [],
            tasks: task.map { [$0] } ?? [],
            checklistItems: checklist.map { [$0] } ?? []
        )
    }
}

